.vc-reviews-pager {
  display: flex;
  flex-direction: column;
  align-items: stretch;
  gap: 0;
  margin: 18px 0 14px;
}

.vc-reviews-pager__meta {
  font-size: 0.9rem;
  opacity: 0.9;
}

.vc-reviews-pager__bar {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  justify-content: space-between;
  gap: 10px 14px;
  width: 100%;
  padding: 12px 16px;
  border-radius: 14px;
  border: 1px solid rgba(255, 255, 255, 0.1);
  background: rgba(12, 10, 8, 0.55);
  box-sizing: border-box;
}

.vc-reviews-pager__bar--simple {
  justify-content: center;
}

.vc-reviews-pager__meta--stats {
  flex: 1 1 12rem;
  text-align: center;
  font-size: 0.88rem;
  font-weight: 600;
  letter-spacing: 0.02em;
  color: rgba(226, 232, 240, 0.92);
  opacity: 1;
  min-width: 0;
}

.vc-reviews-pager__btn {
  flex: 0 0 auto;
  min-width: 7.25rem;
}

@media (max-width: 28rem) {
  .vc-reviews-pager__bar:not(.vc-reviews-pager__bar--simple) {
    display: grid;
    grid-template-columns: 1fr 1fr;
    grid-template-areas:
      "stats stats"
      "prev next";
    gap: 10px 12px;
    justify-items: stretch;
  }

  .vc-reviews-pager__meta--stats {
    grid-area: stats;
    flex: none;
  }

  .vc-reviews-pager__btn[data-reviews-page-prev] {
    grid-area: prev;
  }

  .vc-reviews-pager__btn[data-reviews-page-next] {
    grid-area: next;
  }

  .vc-reviews-pager__btn {
    width: 100%;
    min-width: 0;
  }
}
