.vc-page-transition {
  position: fixed;
  inset: 0;
  z-index: 110000;
  display: flex;
  align-items: center;
  justify-content: center;
  opacity: 0;
  pointer-events: none;
  transition: opacity 0.12s ease-out;
  isolation: isolate;
  background-color: #050403;
  background-image:
    radial-gradient(ellipse 92% 74% at 50% 38%, rgba(6, 58, 46, 0.78) 0%, rgba(6, 18, 20, 0.98) 52%, #030302 100%);
}

.vc-page-transition--vote {
  background-color: #050403;
  background-image:
    radial-gradient(ellipse 92% 74% at 50% 38%, rgba(111, 78, 55, 0.46) 0%, rgba(36, 25, 18, 0.96) 52%, #080605 100%);
}

.vc-page-transition--on {
  opacity: 1;
  pointer-events: auto;
  transition: none;
}

.vc-page-transition-content {
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 0.85rem;
}

.vc-page-transition-vote-iconwrap {
  position: relative;
  display: none;
  width: 10rem;
  height: 10rem;
  margin-bottom: 0.25rem;
}

.vc-page-transition--vote .vc-page-transition-vote-iconwrap {
  display: block;
}

.vc-page-transition-vote-iconring {
  position: absolute;
  inset: 1.15rem;
  border-radius: 9999px;
  background:
    linear-gradient(180deg, rgba(40, 28, 20, 0.34), rgba(20, 14, 10, 0.54)),
    linear-gradient(135deg, rgba(var(--vc-mocha-rgb), 0.34), rgba(var(--vc-sand-rgb), 0.28));
  box-shadow:
    inset 0 0 0 1px rgba(var(--vc-sand-rgb), 0.26),
    0 0 42px rgba(var(--vc-sand-rgb), 0.18);
}

.vc-page-transition-vote-iconring::before {
  content: "";
  position: absolute;
  inset: 0;
  border-radius: inherit;
  border: 4px solid rgba(247, 236, 223, 0.72);
  background: none;
  pointer-events: none;
}

.vc-page-transition-vote-icon {
  position: absolute;
  inset: 0;
  display: flex;
  align-items: center;
  justify-content: center;
  color: rgba(247, 236, 223, 0.98);
  font-size: 3.2rem;
}

.vc-page-transition-vote-spark {
  position: absolute;
  color: rgba(247, 236, 223, 0.9);
  font-size: 1.15rem;
  opacity: 0.95;
  animation: vc-vote-spark 1.7s ease-in-out infinite;
}

.vc-page-transition-vote-spark--a {
  top: 1.2rem;
  right: 1.1rem;
}

.vc-page-transition-vote-spark--b {
  left: 0.95rem;
  top: 4.5rem;
  animation-delay: 0.2s;
}

.vc-page-transition-vote-spark--c {
  left: 1.65rem;
  bottom: 1.55rem;
  animation-delay: 0.45s;
}

.vc-page-transition-spinner {
  width: 3.15rem;
  height: 3.15rem;
  border-radius: 9999px;
  border: 4px solid rgba(var(--vc-reviews-teal-rgb), 0.35);
  border-top-color: rgba(var(--vc-reviews-emerald-rgb), 0.95);
  box-shadow: 0 0 22px rgba(var(--vc-reviews-glow-rgb), 0.28);
  animation: vc-page-spin 0.9s linear infinite;
}

.vc-page-transition--vote .vc-page-transition-spinner {
  display: none;
}

.vc-page-transition-text {
  margin: 0;
  color: rgba(226, 232, 240, 0.82);
  font-size: 1rem;
  font-weight: 500;
}

.vc-page-transition--vote .vc-page-transition-text {
  color: #ffffff;
  font-size: clamp(2rem, 3vw, 3rem);
  font-weight: 800;
  letter-spacing: -0.03em;
}

.vc-page-transition-sub {
  display: none;
  margin: 0;
  color: rgba(213, 219, 236, 0.74);
  font-size: 1rem;
  font-weight: 500;
}

.vc-page-transition--vote .vc-page-transition-sub {
  display: block;
  font-size: clamp(1rem, 1.5vw, 1.35rem);
  color: rgba(247, 236, 223, 0.86);
}

.vc-page-transition-bar {
  display: none;
  position: relative;
  width: min(20rem, 72vw);
  height: 0.6rem;
  margin-top: 0.6rem;
  overflow: hidden;
  border-radius: 9999px;
  background: rgba(var(--vc-mocha-rgb), 0.36);
}

.vc-page-transition--vote .vc-page-transition-bar {
  display: block;
}

.vc-page-transition--login .vc-page-transition-spinner {
  width: 1.45rem;
  height: 1.45rem;
  border-width: 2px;
  border-color: rgba(var(--vc-mocha-rgb), 0.42);
  border-top-color: rgba(var(--vc-sand-rgb), 0.95);
  box-shadow: 0 0 12px rgba(var(--vc-sand-rgb), 0.22);
}

