  border-radius: 1rem;
  border: 1px solid rgba(83, 252, 24, 0.35);
  background:
    linear-gradient(165deg, rgba(12, 18, 10, 0.96), rgba(8, 10, 8, 0.98));
  box-shadow:
    0 14px 36px rgba(0, 0, 0, 0.48),
    0 0 28px rgba(83, 252, 24, 0.12);
  overflow: hidden;
  backdrop-filter: blur(12px) saturate(140%);
  -webkit-backdrop-filter: blur(12px) saturate(140%);
  touch-action: none;
  user-select: none;
  -webkit-user-select: none;
}

.vc-kick-pip--corner-bl {
  left: max(0.75rem, env(safe-area-inset-left, 0px));
  bottom: max(0.85rem, env(safe-area-inset-bottom, 0px));
  right: auto;
  top: auto;
}

.vc-kick-pip--corner-br {
  right: max(0.75rem, env(safe-area-inset-right, 0px));
  bottom: max(0.85rem, env(safe-area-inset-bottom, 0px));
  left: auto;
  top: auto;
}

.vc-kick-pip--corner-tl {
  left: max(0.75rem, env(safe-area-inset-left, 0px));
  top: max(5.75rem, calc(env(safe-area-inset-top, 0px) + 5.25rem));
  right: auto;
  bottom: auto;
}

.vc-kick-pip--corner-tr {
  right: max(0.75rem, env(safe-area-inset-right, 0px));
  top: max(5.75rem, calc(env(safe-area-inset-top, 0px) + 5.25rem));
  left: auto;
  bottom: auto;
}

.vc-kick-pip--free {
  right: auto;
  bottom: auto;
}

.vc-kick-pip--dragging {
  opacity: 0.96;
  box-shadow:
    0 18px 44px rgba(0, 0, 0, 0.55),
