  display: inline-flex;
  align-items: center;
  gap: 0.28rem;
  pointer-events: auto;
}

.vc-kick-pip__drag,
.vc-kick-pip__open,
.vc-kick-pip__float,
.vc-kick-pip__close {
  position: relative;
  z-index: 1;
  width: 1.65rem;
  height: 1.65rem;
  border: 0;
  border-radius: 999px;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  background: rgba(0, 0, 0, 0.55);
  color: #f8fafc;
