  opacity: 1 !important;
  z-index: 3;
  pointer-events: none;
}

.vc-kick-pip--playing.vc-kick-pip--ready .vc-kick-pip__thumb {
  opacity: 0;
  z-index: 0;
  pointer-events: none;
}

.vc-kick-pip--playing.vc-kick-pip--ready .vc-kick-pip__video {
