.vc-notif-fly-card {
  position: fixed;
  z-index: 100001;
  display: flex;
  align-items: flex-start;
  gap: 0.7rem;
  width: min(18.5rem, calc(100vw - 1.5rem));
  margin: 0;
  padding: 0.72rem 0.85rem;
  border-radius: 0.95rem;
  border: 1px solid rgba(94, 234, 212, 0.35);
  background: linear-gradient(145deg, rgba(15, 40, 36, 0.96), rgba(8, 20, 24, 0.98));
  box-shadow:
    0 14px 36px rgba(0, 0, 0, 0.42),
    0 0 0 1px rgba(255, 255, 255, 0.04);
  color: inherit;
  font: inherit;
  text-align: left;
  cursor: var(--vc-cursor-pointer);
  pointer-events: auto;
  transform-origin: var(--vc-pop-ox, 85%) 0;
  animation: vc-notif-pop-in 0.34s cubic-bezier(0.22, 1, 0.36, 1) both;
}

.vc-notif-fly-card:hover {
  filter: brightness(1.06);
}

.vc-notif-fly-card:focus {
  outline: none;
}

.vc-notif-fly-card:focus-visible {
  outline: 2px solid rgba(251, 191, 36, 0.7);
  outline-offset: 2px;
}

.vc-notif-fly-card__ico {
  flex: 0 0 auto;
  width: 2rem;
  height: 2rem;
  border-radius: 999px;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  background: rgba(255, 255, 255, 0.08);
  color: #fde68a;
  font-size: 0.92rem;
}

.vc-notif-fly-card__main {
  min-width: 0;
  flex: 1 1 auto;
  display: flex;
  flex-direction: column;
  gap: 0.15rem;
}

.vc-notif-fly-card__t {
  display: block;
  font-size: 0.86rem;
  font-weight: 700;
  line-height: 1.25;
  color: #ecfdf5;
}

.vc-notif-fly-card__b {
  display: block;
  font-size: 0.74rem;
  line-height: 1.35;
  color: rgba(226, 232, 240, 0.82);
  display: -webkit-box;
  -webkit-line-clamp: 2;
  -webkit-box-orient: vertical;
  overflow: hidden;
}

.vc-notif-fly-card--out {
  animation: vc-notif-pop-out 0.28s ease-in forwards;
  pointer-events: none;
}

