.vc-hw-page {
  display: flex;
  flex-direction: column;
  min-height: 100vh;
  min-height: 100dvh;
  background-color: #0a0706;
  background: radial-gradient(ellipse 120% 80% at 50% -20%, rgba(56, 32, 18, 0.55), transparent 55%),
    linear-gradient(180deg, #0a0706 0%, #120d0a 45%, #0a0706 100%);
}

.vc-hw-theme-bg {
  position: fixed;
  inset: 0;
  z-index: 0;
  overflow: hidden;
  pointer-events: none;
  background: #060403;
  opacity: 1;
  visibility: visible;
}

.vc-hw-theme-bg__video {
  position: absolute;
  inset: 0;
  width: 100%;
  height: 100%;
  object-fit: cover;
  object-position: center center;
  background: #060403;
  filter: brightness(0.72) saturate(0.94) contrast(1.04);
  transform: scale(1.06);
}

.vc-hw-theme-bg__veil {
  position: absolute;
  inset: 0;
  background:
    linear-gradient(180deg, rgba(8, 5, 4, 0.55) 0%, rgba(8, 5, 4, 0.28) 38%, rgba(8, 5, 4, 0.62) 100%),
    radial-gradient(ellipse 90% 70% at 50% 20%, rgba(0, 0, 0, 0.15), rgba(0, 0, 0, 0.55) 100%);
}

