  opacity: 0 !important;
  visibility: hidden !important;
  pointer-events: none !important;
}

body.vc-hw-page.vc-hw-theme-bg-live .vc-hw-theme-bg {
  opacity: 1 !important;
  visibility: visible !important;
}

body.vc-hw-page.vc-hw-cinema-active .vc-hw-theme-bg {
