  opacity: 0.45;
  cursor: not-allowed;
}

.vc-hw-btn--primary {
  border: 1px solid rgba(211, 166, 37, 0.5);
  background: linear-gradient(135deg, rgba(116, 0, 1, 0.85), rgba(58, 0, 1, 0.95));
  color: #fef3c7;
}

