.vc-dash-confirm,
.vc-dialog {
  position: fixed;
  inset: 0;
  z-index: 100700;
  display: flex;
  align-items: center;
  justify-content: center;
  padding: 1rem;
  pointer-events: none;
  visibility: hidden;
  opacity: 0;
  transition: opacity 0.18s ease, visibility 0.18s ease;
}

.vc-dash-confirm.is-open,
.vc-dialog.is-open {
  pointer-events: auto;
  visibility: visible;
  opacity: 1;
}

.vc-dash-confirm__backdrop,
.vc-dialog__backdrop {
  position: absolute;
  inset: 0;
  border: 0;
  margin: 0;
  padding: 0;
  cursor: var(--vc-cursor-pointer);
  background: rgba(8, 6, 5, 0.72);
  backdrop-filter: blur(10px) saturate(140%);
  -webkit-backdrop-filter: blur(10px) saturate(140%);
}

.vc-dash-confirm__panel,
.vc-dialog__panel {
  position: relative;
  z-index: 1;
  width: min(100%, 24rem);
  padding: 1.25rem 1.3rem 1.15rem;
  border-radius: 1.15rem;
  border: 1px solid rgba(212, 168, 136, 0.28);
  background:
    radial-gradient(120% 90% at 0% 0%, rgba(236, 205, 176, 0.14), transparent 55%),
    linear-gradient(160deg, rgba(42, 30, 24, 0.98), rgba(18, 13, 10, 0.96));
  box-shadow:
    0 24px 60px rgba(0, 0, 0, 0.55),
    inset 0 1px 0 rgba(255, 255, 255, 0.06);
  transform: translateY(8px) scale(0.98);
  transition: transform 0.18s ease;
}

.vc-dash-confirm.is-open .vc-dash-confirm__panel,
.vc-dialog.is-open .vc-dialog__panel {
  transform: none;
}

.vc-dash-confirm__icon,
.vc-dialog__icon {
  display: grid;
  place-items: center;
  width: 2.6rem;
  height: 2.6rem;
  margin: 0 0 0.9rem;
  border-radius: 0.85rem;
  background: rgba(248, 113, 113, 0.14);
  color: #fda4af;
  font-size: 1.15rem;
}

.vc-dialog__icon.is-info {
  background: rgba(96, 165, 250, 0.14);
  color: #93c5fd;
}

.vc-dash-confirm__title,
.vc-dialog__title {
  margin: 0;
  color: #f8fafc;
  font-size: 1.15rem;
  font-weight: 800;
  letter-spacing: -0.02em;
}

.vc-dash-confirm__text,
.vc-dialog__text {
  margin: 0.45rem 0 0;
  color: #cbd5e1;
  font-size: 0.92rem;
  line-height: 1.45;
  white-space: pre-wrap;
  overflow-wrap: anywhere;
}

.vc-dash-confirm__text strong,
.vc-dialog__text strong {
  color: #f8fafc;
  font-weight: 700;
}

.vc-dialog__field {
  margin-top: 0.85rem;
  display: flex;
  flex-direction: column;
  gap: 0.4rem;
}

.vc-dialog__field[hidden] {
  display: none !important;
}

.vc-dialog__label {
  font-size: 0.72rem;
  font-weight: 800;
  letter-spacing: 0.12em;
  text-transform: uppercase;
  color: rgba(247, 236, 223, 0.78);
}

.vc-dialog__input {
  width: 100%;
  box-sizing: border-box;
  border: 1px solid rgba(255, 255, 255, 0.12);
  background: rgba(255, 255, 255, 0.04);
  color: #f7efe6;
  border-radius: 0.85rem;
  padding: 0.7rem 0.85rem;
  font: inherit;
  font-size: 0.92rem;
  outline: none;
  transition: border-color 0.15s ease, box-shadow 0.15s ease;
}

.vc-dialog__input::placeholder {
  color: rgba(203, 213, 225, 0.45);
}

.vc-dialog__input:focus {
  border-color: rgba(var(--vc-sand-rgb), 0.45);
  box-shadow: 0 0 0 3px rgba(var(--vc-sand-rgb), 0.12);
}
.vc-dialog__textarea {
  min-height: 8.5rem;
  resize: vertical;
  line-height: 1.45;
  font-family: inherit;
}

.vc-dash-confirm__actions,
.vc-dialog__actions {
  display: flex;
  flex-wrap: wrap;
  gap: 0.55rem;
  margin-top: 1.15rem;
  justify-content: flex-end;
}

.vc-dialog__actions--stack {
  flex-direction: column-reverse;
