html.vc-ptr-ready,
html.vc-ptr-ready body {
  overscroll-behavior-y: contain;
}

.vc-ptr {
  position: fixed;
  left: 50%;
  top: calc(env(safe-area-inset-top, 0px) + 4.85rem);
  z-index: 10240;
  width: 6.1rem;
  margin: 0;
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 0.38rem;
  pointer-events: none;
  opacity: 0;
  transform: translate3d(-50%, -5.6rem, 0);
  transition: opacity 0.2s ease, transform 0.28s cubic-bezier(0.22, 1, 0.36, 1);
}

.vc-ptr.is-on {
  opacity: 1;
  transform: translate3d(-50%, calc(-5.6rem + var(--vc-ptr-y, 0px)), 0);
  transition: none;
}

.vc-ptr.is-snap {
  opacity: 0;
  transform: translate3d(-50%, -5.6rem, 0);
}

.vc-ptr.is-refreshing {
  opacity: 1;
  transform: translate3d(-50%, 0.15rem, 0);
  transition: transform 0.22s cubic-bezier(0.22, 1, 0.36, 1), opacity 0.16s ease;
}

.vc-ptr__disc {
