.vc-staff-stat-sheet {
  position: fixed;
  inset: 0;
  z-index: 120500;
  display: grid;
  place-items: end center;
  padding: 0;
}

.vc-staff-stat-sheet__backdrop {
  position: absolute;
  inset: 0;
